import {reportedFinesPrice,watchMessages} from './alerts.mjs?v=3.6';
import {vehicleProfile,compatiblePower,chargingMinutes,parseTariff,sessionCost} from './energy.mjs?v=3.6';
import {planningCandidates,optimizeJourney,revalidateJourney} from './planner.mjs?v=3.6';
import {stationDetour,roadRoute,roadMatrix} from './roads.mjs?v=3.6';
import {stationReport,reportUrl} from './community.mjs?v=3.6';
import {offlinePut,offlineGet} from './offline.mjs?v=3.6';
import {interpretQuery} from './query.mjs?v=3.6';
import {currentOperating,checkOperating} from './operating.mjs?v=3.6';
import {requestJson} from './services.mjs?v=3.6';
import {webUrl} from './details.mjs?v=3.6';
import {distance} from './core.mjs?v=3.6';
const fields=['name','capacity','soc','reserve','consumption','maxDC','maxAC','mass','temperature'];
const node=(tag,value,cls)=>{const e=document.createElement(tag);if(value!=null)e.textContent=value;if(cls)e.className=cls;return e;};
const local={get(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}},put(key,value){localStorage.setItem(key,JSON.stringify(value));}};
const money=c=>c?`${c.amount.toFixed(2)} ${c.currency}${c.complete?'':' (e pjesshme)'}`:'Çmimi i panjohur';
export function createJourneyTools({map,L,getContext,openStation,openArea,fitAll,closePanels,notice,filterReset}){
 const $=id=>document.getElementById(id);let controller=null,stationController=null,plan=null,excluded=[],routeLayer=null,activeStation=null;let profileRaw=local.get('udhembare-vehicle-v1',{}),watches=local.get('udhembare-watches-v1',[]);if(!Array.isArray(watches))watches=[];watches=watches.slice(0,10).filter(w=>w?.station?.id).map(w=>({...w,freeEnabled:w.freeEnabled??true}));let priceData=null,lastPriceCheck=0;
 const getProfile=()=>vehicleProfile(profileRaw);
 const setOpen=open=>{if(open)closePanels();$('journey-panel').hidden=!open;document.body.classList.toggle('journey-open',open);if(open){$('journey-title').tabIndex=-1;$('journey-title').focus({preventScroll:true});}};
 const openProfile=()=>{for(const f of fields)$('vehicle-'+f).value=profileRaw[f]??(f==='name'?'Audi e-tron 2023':f==='reserve'?15:f==='maxAC'?11:'');$('vehicle-error').textContent='';$('vehicle-dialog').showModal();};
 $('journey-open').addEventListener('click',()=>{setOpen($('journey-panel').hidden);refresh();});$('journey-close').addEventListener('click',()=>setOpen(false));$('vehicle-open').addEventListener('click',openProfile);
 $('vehicle-form').addEventListener('submit',e=>{e.preventDefault();try{const raw=Object.fromEntries(fields.map(f=>[f,$('vehicle-'+f).value]));const p=vehicleProfile(raw);local.put('udhembare-vehicle-v1',raw);profileRaw=raw;controller?.abort();controller=null;plan=null;if(routeLayer&&map)map.removeLayer(routeLayer);routeLayer=null;$('plan-results').replaceChildren();$('plan-cancel').hidden=true;$('vehicle-dialog').close();refresh();if(activeStation&&!$('station-panel').hidden)$('station-smart').replaceChildren(station(activeStation));notice('Profili i '+p.name+' u ruajt. Bateria aktuale përditësohet manualisht.');}catch(error){$('vehicle-error').textContent=error.message;}});
 function refresh(){try{const p=getProfile();$('vehicle-summary').textContent=`${p.name} · ${p.capacity} kWh të përdorshme · ${p.soc}% tani · rezervë ${p.reserve}% · ${p.consumption} kWh/100 km`;}catch{$('vehicle-summary').textContent='Vendos profilin e veturës për të vlerësuar baterinë dhe ndalesat.';}
 const c=getContext();$('plan-generate').disabled=c.busy||!c.search?.line||Boolean(controller);if(c.busy)$('plan-status').textContent='Prit të përfundojë kërkimi i rrugës dhe stacioneve.';if(!c.search?.line&&!controller)$('plan-status').textContent='Krijo fillimisht itinerar te “Në rrugë”. Pastaj llogarit ndalesat.';
 const count=c.candidates?.length||0,visible=c.stations?.length||0;$('filter-summary').textContent=`${visible} të shfaqur nga ${count} me filtrat e kërkimit. ${c.activeOnly?`${Math.max(0,count-visible)} pa konfirmim aktual/jashtë shërbimit janë fshehur.`:''} ${c.radius<1?`Korridori është ${Math.round(c.radius*1000)} m nga rruga.`:`Rrezja/korridori: ${c.radius} km.`}`;
 $('watch-status').textContent=watches.length?`${watches.length} stacione të ndjekura · kontroll çdo 2 minuta kur faqja është e hapur.`:'Njoftimet për lirimin mund t’i aktivizosh te një stacion me status aktual.';}
 $('clear-all-filters').addEventListener('click',filterReset);$('area-search').addEventListener('click',()=>{if(map){const p=map.getCenter();$('area-search').hidden=true;openArea({lat:p.lat,lon:p.lng});}});$('fit-results').addEventListener('click',fitAll);map?.on('dragend',()=>{$('area-search').hidden=false;});
 async function generate(){
  if(controller)return;let p;try{p=getProfile();}catch{$('plan-status').textContent='Plotëso profilin e veturës.';openProfile();return;}
  const c=getContext(),s=c.search;if(c.busy||!s?.line)return;plan=null;if(routeLayer&&map)map.removeLayer(routeLayer);routeLayer=null;controller=new AbortController();const current=controller;$('plan-generate').disabled=true;$('plan-cancel').hidden=false;$('plan-results').replaceChildren();$('plan-status').textContent='Duke kontrolluar distancat rrugore dhe rezervën e baterisë…';
  try{
   const checked=await checkOperating(c.activeOnly?c.stations:c.candidates,{signal:current.signal,minPower:0});const selected=planningCandidates(checked,p,{excluded,isOffline:s=>currentOperating(s).key==='offline'}),start=s.start||s.line[0],end=s.center;
   const matrix=await roadMatrix([start,...selected.map(s=>s.point),end],{signal:current.signal});const budgetValue=$('plan-budget').value,budget=budgetValue===''?null:Number(budgetValue);if(budget!==null&&(!Number.isFinite(budget)||budget<0))throw Error('Buxheti nuk është i vlefshëm.');
   const result=optimizeJourney({profile:p,stations:selected,matrix,routeKm:s.routeKm,terrain:c.terrain,weather:c.weather,mode:$('plan-mode').value,budget});
   $('plan-status').textContent='Duke verifikuar rrugën reale me ndalesat e zgjedhura…';
   const actual=await roadRoute([start,...result.stops.map(x=>x.station.point),end],{signal:current.signal,engine:matrix.engine});if(current.signal.aborted)return;
   plan=revalidateJourney(result,p,actual,c.terrain,s.routeKm,c.weather);renderPlan(plan);drawPlan(plan);$('plan-status').textContent=`Plan i vlerësuar · ${selected.length} kandidatë nga ${c.candidates.length} stacione të kërkimit · verifikuar me OSRM. ${c.terrain&&p.mass?'Terreni i rrugës bazë përfshihet si përafrim.':'Terreni nuk u përfshi në energji: kërkon masën dhe profil lartësie.'} ${p.temperature!==null?'Temperatura është vlera e futur në profil.':c.weather?.some(p=>p.temperature!==null)?'Temperatura përdor parashikimin e rrugës si përafrim.':'Temperatura nuk u përfshi.'}`;
  }catch(error){if(controller===current&&!current.signal.aborted){plan=null;$('plan-status').textContent=error.message;}}finally{if(controller===current){controller=null;$('plan-cancel').hidden=true;$('plan-reset-excluded').hidden=excluded.length===0;refresh();}}
 }
 function drawPlan(result){if(!map||!result.line)return;if(routeLayer)map.removeLayer(routeLayer);routeLayer=L.layerGroup().addTo(map);L.polyline(result.line.map(p=>[p.lat,p.lon]),{color:'#0758d6',weight:5,dashArray:'9 7',opacity:.9,interactive:false}).addTo(routeLayer);
  for(const [i,stop] of result.stops.entries()){const marker=L.marker([stop.station.point.lat,stop.station.point.lon],{icon:L.divIcon({className:'journey-stop-marker',html:`<span>${i+1}</span>`,iconSize:[30,30],iconAnchor:[15,15]}),title:'Ndalesa '+(i+1)+': '+stop.station.name}).addTo(routeLayer);marker.on('click',()=>{setOpen(false);openStation(stop.station);});}
 }
 function renderPlan(result){const box=$('plan-results');box.replaceChildren();const metrics=node('div',null,'plan-metrics');metrics.append(node('strong',Math.round(result.distance)+' km'),node('strong',Math.ceil(result.minutes)+' min gjithsej'),node('strong','Mbërritje ~'+result.soc.toFixed(0)+'%'));box.append(metrics,node('p',result.costKnown&&result.currency?`Kosto e vlerësuar e karikimit: ${result.cost.toFixed(2)} ${result.currency}`:result.stops.length?'Kostoja e plotë nuk dihet për të gjitha ndalesat.':'Nuk nevojitet ndalesë karikimi sipas modelit.','field-note'));
  for(const [i,stop] of result.stops.entries()){const card=node('article',null,'plan-stop');const title=node('button',`${i+1}. ${stop.station.name}`,'plan-station-name');title.type='button';title.addEventListener('click',()=>{setOpen(false);openStation(stop.station);});card.append(title,node('p',`Arritje ~${stop.arrival.toFixed(0)}% → kariko deri ${stop.target}% · ~${Math.ceil(stop.chargeMinutes)} min · ${stop.energy.toFixed(1)} kWh nga rrjeti`),node('small',money(stop.cost)+' · '+currentOperating(stop.station).label));const replace=node('button','Stacioni nuk më përshtatet · Gjej alternativë','secondary');replace.type='button';replace.addEventListener('click',()=>{excluded.push(stop.station.id);generate();});card.append(replace);box.append(card);}

  box.append(node('p','Vlerësimet varen nga konsumi, moti, gjendja e baterisë dhe funksionimi i stacioneve. Kontrollo rezervën reale.','field-note'));
 }
 $('plan-reset-excluded').addEventListener('click',()=>{excluded=[];$('plan-reset-excluded').hidden=true;generate();});
 $('plan-generate').addEventListener('click',generate);$('plan-cancel').addEventListener('click',()=>{controller?.abort();controller=null;$('plan-status').textContent='Llogaritja u anulua.';$('plan-cancel').hidden=true;refresh();});
 function report(station=null){const c=getContext(),p=station?.point||map?.getCenter(),lat=p?.lat,lon=p?.lon??p?.lng;
  $('report-station-id').value=station?.id||'';$('report-kind').value=station?'correction':'missing';$('report-name').value=station?.name||'';$('report-lat').value=lat??'';$('report-lon').value=lon??'';$('report-operator').value=station?.operator||'';$('report-connector').value=station?.connections?.find(c=>['CCS2','Type 2','CHAdeMO'].includes(c.label))?.label||'unknown';$('report-power').value=station?.power||'';$('report-rating').value='';$('report-note').value='';$('report-submit').hidden=true;$('report-state').textContent='';$('report-error').textContent='';$('report-dialog').showModal();}
 function readReport(){return stationReport(Object.fromEntries(['stationId','kind','name','lat','lon','operator','connector','power','rating','note'].map(k=>[k,$(k==='stationId'?'report-station-id':'report-'+k).value])));}
 $('report-missing').addEventListener('click',()=>report());$('report-form').addEventListener('submit',e=>{e.preventDefault();try{const r=readReport();$('report-submit').href=reportUrl(r);$('report-submit').hidden=false;$('report-state').textContent='Raporti është përgatitur. Kontrolloje dhe dërgoje në GitHub; ende nuk është publikuar.';}catch(error){$('report-error').textContent=error.message;}});
 $('report-save').addEventListener('click',()=>{try{const r=readReport(),notes=local.get('udhembare-notes-v1',[]);local.put('udhembare-notes-v1',[r,...(Array.isArray(notes)?notes:[])].slice(0,100));$('report-state').textContent='U ruajt vetëm në këtë telefon. Nuk është publikuar.';}catch(error){$('report-error').textContent=error.message;}});
 $('offline-open').addEventListener('click',()=>{$('offline-dialog').showModal();});$('offline-save').addEventListener('click',async()=>{try{const c=getContext();if(!c.search)throw Error('Kryej fillimisht një kërkim.');await offlinePut('journey',{search:c.search,stations:c.candidates,plan,savedAt:new Date().toISOString()});$('offline-status').textContent='U ruajt rruga dhe '+c.candidates.length+' stacione në këtë telefon.';}catch(error){$('offline-status').textContent=error.message;}});
 $('offline-load').addEventListener('click',async()=>{try{const saved=await offlineGet('journey');if(!saved)throw Error('Nuk ke ende udhëtim të ruajtur offline.');$('offline-list').replaceChildren();$('offline-status').textContent='Kopje e ruajtur më '+new Date(saved.savedAt).toLocaleString('sq-AL')+'. Statusi i stacioneve kërkon internet.';
  if(saved.plan?.line)drawPlan(saved.plan);else if(saved.search.line)drawPlan({line:saved.search.line,stops:[]});
  for(const s of saved.stations){const b=node('button',s.name+' · '+(s.address||s.point.lat.toFixed(3)+', '+s.point.lon.toFixed(3)),'offline-station');b.type='button';b.addEventListener('click',()=>{$('offline-dialog').close();setOpen(false);openStation({...s,operating:{key:'unknown',reason:'Kopje e ruajtur; statusi aktual kërkon internet.'}});});$('offline-list').append(b);}
 }catch(error){$('offline-status').textContent=error.message;}});
 const observe=async()=>{if(document.hidden||!watches.length)return;try{
  if(watches.some(w=>Number.isFinite(w.priceThreshold))&&Date.now()-lastPriceCheck>600000){lastPriceCheck=Date.now();try{priceData=await requestJson('https://public.finescharging.com/v1/locations.geojson',{timeout:8000});}catch{priceData=null;}}
  const updated=await checkOperating(watches.map(w=>w.station),{signal:new AbortController().signal,minPower:0});
  for(const station of updated){const watch=watches.find(w=>w.station.id===station.id);if(!watch)continue;watch.station=station;for(const message of watchMessages(watch,currentOperating(station),reportedFinesPrice(priceData,station.finesId))){notice(message);$('watch-status').textContent=message;if(globalThis.Notification?.permission==='granted')try{new Notification('Udhëmbarë',{body:message,icon:'./icon.svg?v=3.6'});}catch{}}}
  local.put('udhembare-watches-v1',watches);
 }catch{}};
 setInterval(observe,120000);
 $('allow-notifications').addEventListener('click',async()=>{if(!globalThis.Notification){$('watch-status').textContent='Njoftimet e sistemit nuk mbështeten; sinjalet mbeten brenda faqes.';return;}let permission;try{permission=await Notification.requestPermission();}catch{$('watch-status').textContent='Njoftimet nuk u aktivizuan. Sinjalet brenda faqes mbeten të përdorshme.';return;}$('watch-status').textContent=permission==='granted'?'Njoftimet u lejuan. Kontrolli punon vetëm sa faqja është e hapur.':'Njoftimet e sistemit nuk u lejuan; sinjalet mbeten brenda faqes.';});
 function station(station){activeStation=station;stationController?.abort();stationController=new AbortController();const signal=stationController.signal,section=node('section',null,'station-smart');
  const controls=node('div',null,'journey-toolbar');const vehicle=node('button','⚡ Audi im','secondary');vehicle.type='button';vehicle.addEventListener('click',openProfile);const reporting=node('button','Raporto / vlerëso','secondary');reporting.type='button';reporting.addEventListener('click',()=>report(station));controls.append(vehicle,reporting);section.append(controls);
  const c=getContext();if(c.search?.line){const button=node('button','↗ Llogarit devijimin real nga itinerari','detour-button');button.type='button';const value=node('p','Krahasim nga nisja e itinerarit deri te destinacioni.','field-note');button.addEventListener('click',async()=>{button.disabled=true;value.textContent='Duke llogaritur dy rrugët…';try{const result=await stationDetour(c.search.start||c.search.line[0],station.point,c.search.center,{signal});if(signal.aborted)return;value.textContent=`+${result.extraKm.toFixed(1)} km · +${Math.ceil(result.extraMinutes)} min devijim rrugor · OSRM, pa trafik aktual.`;}catch(error){if(!signal.aborted)value.textContent=error.message;}finally{button.disabled=false;}});section.append(button,value);}
  const cost=node('details',null,'station-cost');cost.append(node('summary','Sa energji, kohë dhe para kërkon ndalesa?'));
  const targetLabel=node('label','Kariko deri në %'),target=node('input');target.type='number';target.min='1';target.max='100';target.value='80';targetLabel.append(target);const amount=node('p',null,'field-note');const compute=()=>{try{const p=getProfile(),connection=compatiblePower(station,p),to=Number(target.value);if(to<=p.soc)throw Error('Objektivi duhet të jetë mbi baterinë aktuale në profil.');const mins=chargingMinutes(p,connection,p.soc,to),energy=p.capacity*(to-p.soc)/100/p.efficiency,price=sessionCost(parseTariff(station.price),energy,mins);amount.textContent=`Nga ${p.soc}% e futur në profil → ${to}% · ~${Math.ceil(mins)} min · ${energy.toFixed(1)} kWh nga rrjeti · ${money(price)}. Kurba është orientuese. Tarifa e plotë/parkimi kontrollohen te operatori.`;}catch(error){amount.textContent=error.message+' Plotëso “Audi im” dhe kontrollo fuqinë e lidhësit.';}};target.addEventListener('input',compute);compute();cost.append(targetLabel,amount);section.append(cost);
  if(station.finesId){const existing=()=>watches.find(w=>w.station.id===station.id);const watch=node('button',existing()?.freeEnabled?'Hiq njoftimin për lirimin':'Njoftomë kur lirohet · app-i i hapur','secondary');watch.type='button';
   const entry=()=>{let w=existing();if(!w){if(watches.length>=10)throw Error('Mund të ndjekësh deri në 10 stacione.');const state=currentOperating(station);w={station,available:state.key==='working'?state.available>0:null,freeEnabled:false,priceThreshold:null};watches.push(w);}return w;};
   const persist=()=>{watches=watches.filter(w=>w.freeEnabled||Number.isFinite(w.priceThreshold));local.put('udhembare-watches-v1',watches);refresh();};
   watch.addEventListener('click',()=>{try{const w=entry();w.freeEnabled=!w.freeEnabled;watch.textContent=w.freeEnabled?'Hiq njoftimin për lirimin':'Njoftomë kur lirohet · app-i i hapur';persist();}catch(error){notice(error.message);}});section.append(watch);
   const priceWatch=node('details',null,'price-watch');priceWatch.append(node('summary','Njoftim për çmimin · EUR/kWh'));const label=node('label','Pragu për diapazonin e raportuar'),threshold=node('input');threshold.type='number';threshold.min='0';threshold.max='10';threshold.step='.01';threshold.value=existing()?.priceThreshold??'';threshold.placeholder='P.sh. 0.45';label.append(threshold);const save=node('button','Ruaj pragun · bosh për ta hequr','secondary');save.type='button';const state=node('p','Kontrollohet çdo 10 minuta kur faqja është e hapur. Duhet çmim aktual EUR/kWh nga Fines; nuk është ofertë e garantuar.','field-note');save.addEventListener('click',()=>{try{const value=threshold.value===''?null:Number(threshold.value);if(value!==null&&(!Number.isFinite(value)||value<0||value>10))throw Error('Pragu duhet të jetë 0–10 EUR/kWh.');const w=entry();w.priceThreshold=value;w.below=null;persist();state.textContent=value===null?'Pragu u hoq.':'Pragu u ruajt. Njoftohesh për të dhëna të freskëta që e plotësojnë.';if(value!==null)void observe();}catch(error){state.textContent=error.message;}});priceWatch.append(label,save,state);section.append(priceWatch);
  }
  const amenities=node('details',null,'station-amenities');amenities.append(node('summary','Kafe, tualet dhe shërbime pranë stacionit'));if(station.info?.metadata?.facilities)amenities.append(node('p',station.info.metadata.facilities));const find=node('button','Kërko shërbime rreth 200 m','secondary');find.type='button';const nearby=node('div');find.addEventListener('click',async()=>{find.disabled=true;nearby.textContent='Duke kërkuar në OpenStreetMap…';try{const p=station.point,query=`[out:json][timeout:8];nwr(around:200,${p.lat},${p.lon})["amenity"~"^(cafe|restaurant|toilets|fast_food)$"];out tags center;`,data=await requestJson('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(query),{signal,timeout:10000});nearby.replaceChildren();if(!Array.isArray(data.elements))throw Error('Shërbimet nuk u morën.');for(const e of data.elements.slice(0,15)){const at=e.center||e;if(!Number.isFinite(at.lat)||!Number.isFinite(at.lon))continue;const labels={cafe:'Kafe',restaurant:'Restorant',toilets:'Tualet',fast_food:'Ushqim'},a=node('a',(e.tags.name||labels[e.tags.amenity]||'Shërbim')+' · ~'+Math.round(distance(p,{lat:at.lat,lon:at.lon})*1000)+' m në vijë ajrore','nearby-amenity');a.href=`https://www.openstreetmap.org/${e.type}/${e.id}`;a.target='_blank';a.rel='noopener noreferrer';nearby.append(a);}if(!nearby.children.length)nearby.textContent='Nuk u gjetën të dhëna të regjistruara; kjo nuk provon mungesën e shërbimeve.';nearby.append(node('small','© OpenStreetMap contributors · ODbL'));}catch(error){if(!signal.aborted)nearby.textContent='Shërbimi nuk u përgjigj. Provo përsëri.';}finally{find.disabled=false;}});amenities.append(find,nearby);section.append(amenities);
  const personal=local.get('udhembare-notes-v1',[]);for(const r of (Array.isArray(personal)?personal:[]).filter(r=>r.stationId===station.id).slice(0,5))section.append(node('p',`Shënimi yt · ${new Date(r.observedAt).toLocaleDateString('sq-AL')}${r.rating?' · '+r.rating+'/5':''}: ${r.note||r.kind}`,'personal-note'));
  const community=node('div');section.append(community);requestJson(new URL('./data/community.json',import.meta.url).href,{signal,timeout:4000}).then(data=>{if(signal.aborted||activeStation!==station)return;for(const r of (data.reports||[]).filter(r=>r.stationId===station.id).slice(0,8)){const row=node('p',`${r.author} · ${new Date(r.observedAt).toLocaleDateString('sq-AL')}${r.rating?' · '+r.rating+'/5':''}: ${r.note||r.kind}`,'personal-note');const source=node('a',' Burimi ↗');const safe=webUrl(r.url);if(safe)source.href=safe;source.target='_blank';source.rel='noopener noreferrer';row.append(source);community.append(row);}if(community.children.length)community.prepend(node('strong','Raporte të miratuara · jo status aktual'));}).catch(()=>{});
  return section;
 }
 $('search-form').addEventListener('submit',()=>{$('query-interpretation').textContent='';const input=$('destination'),parsed=interpretQuery(input.value);if(!parsed||!parsed.place)return;if(parsed.route)document.querySelector('[data-mode="route"]').click();if(parsed.connector)$('connector').value=parsed.connector;if(parsed.power!==null){const value=String(parsed.power);if(![...$('power').options].some(o=>o.value===value))$('power').add(new Option(value+' kW+',value));$('power').value=value;}if(parsed.active)$('only-active').checked=true;if(parsed.open24)$('open-24').checked=true;input.value=parsed.place;$('query-interpretation').textContent='U kuptua: '+[parsed.place,parsed.connector,parsed.power?parsed.power+' kW+':'',parsed.open24?'24/7':''].filter(Boolean).join(' · ');},{capture:true});
 function reset(){controller?.abort();controller=null;$('plan-cancel').hidden=true;$('plan-generate').disabled=true;$('plan-reset-excluded').hidden=true;stationController?.abort();plan=null;excluded=[];if(routeLayer&&map)map.removeLayer(routeLayer);routeLayer=null;$('plan-results').replaceChildren();setOpen(false);}
 return {station,refresh,reset,close:()=>setOpen(false),closeStation:()=>{stationController?.abort();stationController=null;activeStation=null;}};
}
